class _Inert:
    """Permissive stand-in for a boosting classifier that the C1 path never fits.

    It must survive the authors' `build_models_balanced(...)` constructor calls
    (arbitrary kwargs, sklearn-style get_params/set_params) but is never fitted.
    """

    def __init__(self, *args, **kwargs):
        self._args = args
        self._kwargs = dict(kwargs)

    def fit(self, X, y=None, *args, **kwargs):
        self._fit_shape = getattr(X, "shape", None)
        return self

    def predict(self, X, *args, **kwargs):
        import numpy as np
        return np.zeros(len(X), dtype=int)

    def predict_proba(self, X, *args, **kwargs):
        import numpy as np
        p = np.zeros((len(X), 2))
        p[:, 0] = 1.0
        return p

    def get_params(self, deep=True):
        return {}

    def set_params(self, **params):
        self._kwargs.update(params)
        return self

    def __getattr__(self, name):
        # any other attribute access becomes a no-op callable (never used here)
        if name.startswith("__") and name.endswith("__"):
            raise AttributeError(name)
        def _noop(*args, **kwargs):
            return None
        return _noop


class _StubModule(types.ModuleType):
    """Module whose missing attributes resolve to _Inert classes/functions."""

    def __getattr__(self, name):
        if name.startswith("__") and name.endswith("__"):
            raise AttributeError(name)
        return _Inert


def _stub(name):
    if name in sys.modules:
        return
    mod = _StubModule(name)
    mod.__dict__["_Inert"] = _Inert
    sys.modules[name] = mod

