def git_status_author_files(restored_paths):
    """Classify the authors' working-tree differences vs HEAD.

    Expected: deletions of the non-restored binary assets (the '|' PNG cannot be
    materialized on NTFS). Anything else would mean an author source file was
    modified.
    """
    try:
        p = subprocess.run(["git", "status", "--porcelain"],
                           cwd=os.path.join(HERE, "repo"), capture_output=True, text=True)
        lines = [l for l in p.stdout.splitlines() if l.strip()]
        skipped_binaries, modified_author_sources = [], []
        for line in lines:
            path = line[3:].strip()
            if path in restored_paths:
                modified_author_sources.append(line)
            else:
                skipped_binaries.append(line)
        return {
            "all_differences": lines,
            "skipped_binaries_and_ignored": skipped_binaries,
            "modified_author_sources": modified_author_sources,
        }
    except Exception as exc:
        return {"error": str(exc)}

